buy_code:
if (
    데이터길이 >= {min_len}
    and {entry_start} <= 시분초 <= {entry_end}
    and 시가총액 <= {cap_max}
    and 현재가 >= 최저현재가({range_window}, 1) + (최고현재가({range_window}, 1) - 최저현재가({range_window}, 1)) * {range_pos_min} / 100
    and 현재가 >= 최고현재가({range_window}, 1) * (1 - {high_gap_max} / 100)
    and 현재가 <= 최고현재가({range_window}, 1) * (1 - {high_gap_min} / 100)
    and 분당거래대금 >= 분당거래대금평균({money_avg_window}, 1) * {money_burst_mult}
    and 누적분당매수수량({flow_window}) >= 누적분당매도수량({flow_window}) * {flow_ratio_min}
    and 전일동시간비 >= {same_time_ratio_min}
):
    self.Buy()

sell_code:
if 수익률 >= {take_hard}:
    self.Sell()
elif 수익률 <= -{stop_hard}:
    self.Sell()
elif 보유시간 >= {max_hold_sec}:
    self.Sell()
elif 수익률 >= {trail_trigger} and 현재가 <= 최고현재가({trail_window}, 1) * (1 - {trail_gap} / 100):
    self.Sell()
